import{_ as o,o as r,c as t,a2 as a}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse('{"title":"Agent 核心研究与竞品动态 · 2026-09-11","description":"2026-09-11 Agent 核心研究者、协议、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","frontmatter":{"title":"Agent 核心研究与竞品动态 · 2026-09-11","description":"2026-09-11 Agent 核心研究者、协议、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-09-11.md","filePath":"zh/runtime/daily-intelligence/2026-09-11.md","lastUpdated":1789085311000}'),n={name:"zh/runtime/daily-intelligence/2026-09-11.md"};function i(s,e,l,p,d,c){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="agent-核心研究与竞品动态-·-2026-09-11" tabindex="-1">Agent 核心研究与竞品动态 · 2026-09-11 <a class="header-anchor" href="#agent-核心研究与竞品动态-·-2026-09-11" aria-label="Permalink to &quot;Agent 核心研究与竞品动态 · 2026-09-11&quot;">​</a></h1><blockquote><p>Asia/Shanghai · 仅收录达到 meaningful new developments 阈值的公开技术与产品变化。</p></blockquote><p><a href="./">返回每日动态索引</a></p><h2 id="当日结论" tabindex="-1">当日结论 <a class="header-anchor" href="#当日结论" aria-label="Permalink to &quot;当日结论&quot;">​</a></h2><p>今天最强的共振不是“又多了什么 Agent 功能”，而是 <strong>静态配置、历史会话和曾经获得的批准，都越来越不能被当作当前执行权。</strong> MCP 正把服务器发现与实时能力协商拆开；Codex 在权限扩大、插件选择和 AGENTS.md 变化后重新计算有效运行上下文；Superset、Orca 则分别用 workspace-bound token 和 live provider catalog 证明“当前是谁、当前能做什么”。</p><h2 id="_1-david-soria-parra-sam-morrow-·-mcp-server-cards-预连接发现与运行时能力正式拆开" tabindex="-1">1. David Soria Parra / Sam Morrow · MCP Server Cards：预连接发现与运行时能力正式拆开 <a class="header-anchor" href="#_1-david-soria-parra-sam-morrow-·-mcp-server-cards-预连接发现与运行时能力正式拆开" aria-label="Permalink to &quot;1. David Soria Parra / Sam Morrow · MCP Server Cards：预连接发现与运行时能力正式拆开&quot;">​</a></h2><p><strong>状态：SEP 文本已标记 Final；GitHub PR #2127 仍 OPEN / 未合入。</strong></p><p>MCP 的 <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/pull/2127" target="_blank" rel="noreferrer">SEP-2127</a> 在当前提案文本中已标记 <strong>Final</strong>。该提案由 David Soria Parra、Sam Morrow、Tadas Antanavicius 代表 Server Card Working Group 提出，目标是在建立连接前提供标准化的 HTTP MCP Server discovery。</p><p>核心设计包括：Server Card 公开服务器身份、remote endpoint 和 supported protocol versions；域级发现可通过 <code>/.well-known/ai-catalog.json</code> 链接或嵌入卡片；推荐的卡片路径为 <code>&lt;streamable-http-url&gt;/server-card</code>。详细 wire format 由 <code>experimental-ext-server-card</code> 扩展仓库维护。</p><p>最重要的边界不是“多一个 discovery 文件”，而是提案明确 <strong>不在静态 Server Card 中声明 tools/resources/prompts，也不声明 MCP capabilities/extensions</strong>。理由是这些能力可能随 authenticated user、session、配置、feature flag 和 deployment state 变化。连接建立后仍以 live <code>server/discover</code> / 协议协商为权威；若静态卡与实时值冲突，客户端应优先实时值。</p><p><strong>为什么重要：</strong> 这给 Agent Host 准入一个非常清楚的分层：<code>Discoverable Identity ≠ Runtime Capability ≠ Current Authorization</code>。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> Host Dependency Center 可以借鉴同一原则：Server/Host Card 负责发现与版本定位；真正准入仍要做 live capability probe、当前身份验证和角色级真实测试，不能把静态声明直接升级成兼容或授权事实。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Would a future Server Card profile expose a stable capability-manifest identity/hash without advertising user-dependent capabilities themselves, so admission can bind discovery to a later live conformance result?</em></p><h2 id="_2-openai-codex-权限扩大、插件切换和-agents-md-更新都会使旧运行上下文失效" tabindex="-1">2. OpenAI Codex：权限扩大、插件切换和 AGENTS.md 更新都会使旧运行上下文失效 <a class="header-anchor" href="#_2-openai-codex-权限扩大、插件切换和-agents-md-更新都会使旧运行上下文失效" aria-label="Permalink to &quot;2. OpenAI Codex：权限扩大、插件切换和 AGENTS.md 更新都会使旧运行上下文失效&quot;">​</a></h2><p><strong>状态：#44617 MERGED；#44655 MERGED；#44675 MERGED。</strong></p><p>Codex 在同一时间窗口连续合入三项很有代表性的边界修复：</p><ul><li><a href="https://github.com/openai/codex/pull/44617" target="_blank" rel="noreferrer">#44617</a>：一个 <code>exec_command</code> 若请求 <code>with_additional_permissions</code>，不能复用此前只覆盖较窄权限的 Guardian v2 cached approval。现在这种未重新评分的 permission widening 会使缓存分数失效并 <strong>fail closed</strong> 为 <code>scoring_failure</code>。</li><li><a href="https://github.com/openai/codex/pull/44655" target="_blank" rel="noreferrer">#44655</a>：thread-level <code>disabled_plugin_ids</code> 现在真正作用到 plugin skills、recommendations、hooks、MCP servers 和 model-visible app tools；插件选择变化只在下一 task 开始时激活，避免 pending settings 改写当前 runtime。MCP tool approval key 也加入 plugin identity，防止不同插件共享一个模糊批准。</li><li><a href="https://github.com/openai/codex/pull/44675" target="_blank" rel="noreferrer">#44675</a>：长期 root thread 不再永久使用启动时的全局 <code>AGENTS.md</code>。Codex 会在 model-request boundary 重新加载 global instructions，包括同一 turn 的 tool 之后；新 subagent 继承父线程当时已经应用的 instruction snapshot，Guardian reviewer reuse 也会考虑 instruction 已变化这一事实。</li></ul><p><strong>为什么重要：</strong> 以前的 approval、plugin selection、instruction snapshot 都只是某个上下文下的事实；一旦 effect scope、插件主体或上位指令变化，旧证据不能自动继续授权。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 这非常接近 CodeFlowMu 的 Host 插件化和“每次 agent 编程都要看宪法”要求。建议把运行授权绑定到 <code>Policy/Instruction Revision + Plugin Identity + Requested Effect Scope + Authority Epoch</code>，并规定 widening 或 revision change 必须重新裁决。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Do you expect Guardian approval cache keys to converge on one explicit policy-context digest covering effective instructions, plugin identity and normalized permission scope?</em></p><h2 id="_3-superset-cloud-workspace-从-blaxel-迁往-vercel-sandbox-手机-pages-review-已正式合入" tabindex="-1">3. Superset：Cloud Workspace 从 Blaxel 迁往 Vercel Sandbox；手机 Pages Review 已正式合入 <a class="header-anchor" href="#_3-superset-cloud-workspace-从-blaxel-迁往-vercel-sandbox-手机-pages-review-已正式合入" aria-label="Permalink to &quot;3. Superset：Cloud Workspace 从 Blaxel 迁往 Vercel Sandbox；手机 Pages Review 已正式合入&quot;">​</a></h2><p><strong>状态：#7408 OPEN；#7367 MERGED。</strong></p><p><a href="https://github.com/superset-sh/superset/pull/7408" target="_blank" rel="noreferrer">Superset #7408</a> 是今天竞品侧最值得看的结构性变化之一。由于 Blaxel 被收购，Superset 正把 Cloud Workspace 迁到 Vercel Sandbox，并借迁移重做一部分 Host/Sandbox 信任边界：</p><ul><li>persistent sandbox 使用 4 小时 session timeout，只有真正打开 workspace 才延长；</li><li>fork 从已停止 golden snapshot 创建；</li><li>organization model key 在 egress firewall 注入；若用户为某 provider 配置 personal credential/environment，则抑制该 provider 的组织级 brokered key；</li><li>Vercel sandbox port 是公开 URL，因此 host-service 成为认证门。API 签发 <strong>10 分钟 Ed25519 token，并绑定单一 workspace ID</strong>；sandbox 只持公钥；无 token、外 workspace token 或伪造 token 均被拒绝；</li><li>addressing 与 waking 被明确拆开：查询地址/状态不会唤醒，只有 open workspace 才会启动；snapshot 会终止当前 session 并成为下一次恢复点。</li></ul><p>开发分支已经记录真实 Vercel 项目的验证：workspace 约 14 秒 ready，fork 约 6 秒；stop 后 sidebar polling 两分钟不唤醒，重新打开后约 20–30 秒恢复 pane/scrollback；token refresh 连续 35 分钟无 401。但 PR 仍 OPEN，不能当成正式发布能力。</p><p>与此同时，此前监测的移动端 <a href="https://github.com/superset-sh/superset/pull/7367" target="_blank" rel="noreferrer">#7367</a> 已在 9 月 10 日正式 <strong>MERGED</strong>：手机端可以浏览 Agent 发布的 Pages，通过 signed <code>viewUrl</code> + WebView 读取，并对页面元素做 comment、quick feedback、thread/pin 等 review 操作。当前 <code>remove/approve</code> 仍以普通评论文本表达，typed intent 还没有完全落地。</p><p><strong>为什么重要：</strong> Superset 正同时把 Cloud Sandbox 和 Mobile Review 做成产品一等面：电脑负责执行，手机负责看成果和反馈；Cloud Host 则拥有独立 workspace identity 与短时访问凭证。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 非常接近“本地/云 Host + 手机审批/证据终端”的数字员工工作站路线。尤其值得借鉴 <code>Address ≠ Wake</code>、workspace-bound bearer、个人凭证覆盖组织 broker，以及手机端只承载 review/control 而非缩小 PC UI。</p><p><strong>学习：非常高｜竞争风险：很高｜雷达判断：上调。</strong> 建议继续作为“主雷达候选”；若 #7408 合入并完成 production deployment / mobile E2E，可正式升入主雷达。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>When a stopped Vercel workspace is reopened, will the new sandbox/process generation be explicitly bound to the previous workspace identity and current credential projection so session continuity cannot imply stale host authority?</em></p><h2 id="_4-paperclip-board-api-key-正从-一个管理员-token-升级成可审计的最小权限合同" tabindex="-1">4. Paperclip：Board API Key 正从“一个管理员 Token”升级成可审计的最小权限合同 <a class="header-anchor" href="#_4-paperclip-board-api-key-正从-一个管理员-token-升级成可审计的最小权限合同" aria-label="Permalink to &quot;4. Paperclip：Board API Key 正从“一个管理员 Token”升级成可审计的最小权限合同&quot;">​</a></h2><p><strong>状态：#10972 OPEN；已完成最新 master rebase 与多轮安全验证，但尚未合入。</strong></p><p>Paperclip <a href="https://github.com/paperclipai/paperclip/pull/10972" target="_blank" rel="noreferrer">#10972</a> 经过近期重构与安全审查后已经形成相当完整的 board automation authorization contract：</p><ul><li>versioned scope schema 与 canonical <strong>59-permission</strong> vocabulary；</li><li>新 board key 不允许 null scope，legacy key 明确标记并暂时保留旧的 unrestricted 行为；</li><li>每次请求重新检查 key 与 owner，并把 stored key scope 与 <strong>live owner authority</strong> 取交集；company access 从 authoritative rows 推导；</li><li>allow / deny 都写 audit record，mutation 与 audit 耦合，并有 self-revoke 规则；</li><li>仓库加入 board-reachable route inventory，新/改 route 如果没有显式声明 policy metadata，CI 直接失败；</li><li>role demotion、grant provenance、authorization order、audit atomicity 等都有专项测试。</li></ul><p>PR 自己也明确保留一个重要限制：PostgreSQL transaction 无法回滚 object store、filesystem、process、provider 或 live publication 等外部副作用，因此这些效果仍需要 durable intent/outbox、稳定 idempotency key、retry state 和 compensation。</p><p><strong>为什么重要：</strong> 这把“API Key 有权限”进一步拆成 <code>Stored Scope ∩ Current Owner Authority ∩ Current Resource/Route Policy</code>。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 对 ADMIN/PM/Host 插件控制很有参考意义：长期凭证不应永久携带创建时权限；角色降级、组织范围变化后，下一次调用必须按当前 authority 重算。</p><p><strong>学习：非常高｜竞争风险：很高｜雷达判断：维持 Paperclip 一线 Runtime/控制面竞品。</strong></p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Will non-database side effects eventually require an authorization receipt that binds the scoped board key, live owner authority, effect precondition and durable outbox/idempotency identity?</em></p><h2 id="_5-openai-agents-sdk-python-hitl-中断恢复后-未发送的-tool-output-也必须保持因果完整" tabindex="-1">5. OpenAI Agents SDK Python：HITL 中断恢复后，未发送的 Tool Output 也必须保持因果完整 <a class="header-anchor" href="#_5-openai-agents-sdk-python-hitl-中断恢复后-未发送的-tool-output-也必须保持因果完整" aria-label="Permalink to &quot;5. OpenAI Agents SDK Python：HITL 中断恢复后，未发送的 Tool Output 也必须保持因果完整&quot;">​</a></h2><p><strong>状态：#4947 MERGED。</strong></p><p><a href="https://github.com/openai/openai-agents-python/pull/4947" target="_blank" rel="noreferrer">openai-agents-python #4947</a> 修复了一个非常具体但很有架构价值的恢复问题：同一个 model response 可以同时包含一个需要人工批准的 tool call，以及一个调用不存在 tool 的 call。Runner 会先在本地为不存在的工具生成 error output，然后因为另一调用等待 approval 而中断。</p><p>此前在 <code>conversation_id</code>、<code>previous_response_id</code> 或 <code>auto_previous_response_id</code> 这类 server-managed continuation 下恢复时，那份已经生成但<strong>尚未发送给 Server/Model</strong> 的 tool-not-found output 会被误认为已交付，最终造成 server 保留一个 function call 却没有对应 output。新实现以最近一次 model response 的 tool-call IDs 作为中断 turn 的权威集合，同时先识别 server-owned items，保证本地未发 output 被补交，而已经交付的 output 不会重复发送。测试还覆盖了两次分阶段 approval，要求每个 tool output 最终只发送一次。</p><p><strong>为什么重要：</strong> Resume 不只是“回到某个状态”，还必须保持 <code>Call → Local Result → Delivered Result</code> 的因果完整性和 exactly-once delivery 语义。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> FCoP/Runtime 中任何 WAIT/HITL/REVIEW 中断都应区分：事实是否已经产生、是否已经持久化、是否已经送达下一主体。三者不能只用一个 Completed 标志代替。</p><p><strong>值得互动：高。</strong> 技术切入：<em>Would an explicit per-tool effect/result delivery ledger make interrupted-run recovery simpler than reconstructing unsent outputs from the latest model response?</em></p><h2 id="_6-orca-恢复出的-model-配置不能覆盖-provider-当前真实能力" tabindex="-1">6. Orca：恢复出的 Model 配置不能覆盖 Provider 当前真实能力 <a class="header-anchor" href="#_6-orca-恢复出的-model-配置不能覆盖-provider-当前真实能力" aria-label="Permalink to &quot;6. Orca：恢复出的 Model 配置不能覆盖 Provider 当前真实能力&quot;">​</a></h2><p><strong>状态：#19946 OPEN。</strong></p><p>Orca <a href="https://github.com/stablyai/orca/pull/19946" target="_blank" rel="noreferrer">#19946</a> 记录了一个真实 Claude structured-session 故障：session restore 可以重放一个过去有效、现在已被 provider 下架的 model ID；mid-session API（包括 mobile <code>agentSession.setOption</code>）也可以发送任意 ID。Claude Code 的 <code>setModel()</code> 对不存在的 model 仍可能成功返回，但后续每个 turn 都 <code>is_error=true</code>、零 token，使 session 看起来活着却永远没有成果。</p><p>候选修复在真正写入 model 前，先读取 <strong>live session 自己的 <code>supportedModels()</code></strong> 并拒绝 provider 未列出的 model；restore 遇到 stale choice 则跳过，让 provider 当前 model 保持权威。作者同时明确边界：provider catalog 只能证明 provider 列出该模型，不能证明当前 account/credential 有 entitlement；如果 <code>list_models</code> 根本不可用或为空，为兼容旧 CLI 当前选择不拒绝。</p><p><strong>为什么重要：</strong> <code>Persisted Configuration ≠ Current Capability</code>。恢复逻辑不能因为“这是上一次保存的配置”就绕过本轮真实 Host/Provider admission。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 这正好支持 Host 准入中心的“发现版本 → 采集真实能力 → 与基线差异 → 角色真实测试 → ADMIN adopt”路径。静态 config 和旧 session 都只能是候选输入，不是当前能力事实。</p><p><strong>学习：非常高｜竞争风险：中高｜雷达判断：继续提高 Orca 的 Host capability / recovery 权重。</strong></p><p><strong>值得互动：高。</strong> 技术切入：<em>Would you split provider-listed capability and credential entitlement into two explicit admission facts, so restore can fail closed only when the relevant evidence is actually available?</em></p><h2 id="跨项目共振" tabindex="-1">跨项目共振 <a class="header-anchor" href="#跨项目共振" aria-label="Permalink to &quot;跨项目共振&quot;">​</a></h2><p>今天最值得保留的原则是：</p><blockquote><p><strong>历史可以恢复，身份可以发现，配置可以持久化；但当前执行权只能由当前上下文重新证明。</strong></p></blockquote><p>MCP Server Card 主动拒绝把动态 tools/capabilities 固化进静态发现文档；Codex 在 permission widening、plugin selection 和 instruction revision 变化后让旧批准/上下文失效；Superset 用 workspace-bound token 把公开 sandbox endpoint 收回到具体 workspace；Paperclip 将长期 key scope 与 live owner authority 取交集；Orca 在恢复 model choice 前重新询问 live provider catalog；Agents SDK 则补齐中断前后 tool-result delivery 的因果链。</p><p>对 CodeFlowMu/FCoP，可以进一步固定为：</p><p><strong>Discovery Identity → Live Capability Evidence → Principal/Scope → Policy Revision → Call-time Authority → Effect/Result Delivery → Replay Eligibility</strong>。</p><p>这里最关键的是前两项的分离：<strong>发现某个 Host/Server/Model 存在，不等于证明它现在对这个账号、这个工作区、这个角色可用。</strong></p><h2 id="双源核查说明" tabindex="-1">双源核查说明 <a class="header-anchor" href="#双源核查说明" aria-label="Permalink to &quot;双源核查说明&quot;">​</a></h2><p>本轮同时核查了公开社交/官方活动与 GitHub 一手变更。Microsoft Reactor 的 MCP Live 官方页面显示 Sam Morrow 仍直接讲解 “MCP: Server, Client &amp; Protocol at GitHub”，Clare Liguori 讲解 event-driven agents powered by MCP，说明名单中的协议/Runtime 工程者仍直接参与公开技术传播；但公开页面未提供足以超过上述 GitHub 一手材料的新增技术细节，因此未把活动宣传单独列为 development。</p><p>Yue Zhao 的 <code>grade</code> 与 <code>auditable</code> 自 2026-09-10 UTC 起未发现新的 GitHub commit；本轮也没有发现身份可可靠确认、且技术增量超过上述一手变更的本人 X 讨论，因此没有用营销转发或疑似账号补数。Cursor 官方侧未发现比此前已报告的 Self-Hosted Machines 更晚、且达到本监测阈值的新正式 Agent 架构发布。</p>',64)])])}const h=o(n,[["render",i]]);export{g as __pageData,h as default};
